import { GolfBallPhysics } from '../physics/GolfBallPhysics';
import { PhysicsWorld } from '../physics/PhysicsWorld';
import { HoleRuntime } from './HoleRuntime';

const STEP = 1 / 60;
const MASS = 0.75;
const RADIUS = GAME_CONFIG.physics.ballRadius;
const BALL_OPTIONS = { mass: MASS, friction: 0.5, restitution: 0.45, rollingResistance: 0, airResistance: 0 };

beforeAll(async () => {
  await RAPIER.init();
});

function holeOf(course: Course, id: string): Hole {
  const hole = course.holes.find((entry) => entry.id === id);
  if (!hole) throw new Error('missing hole ' + id);
  return hole;
}

/** Mirrors the fixed step Game runs: movers, then the sensor volumes, then the ball. */
class Rig {
  readonly physics = new PhysicsWorld();
  readonly builder = new HoleSceneBuilder();
  readonly runtime: HoleRuntime;
  readonly ball: GolfBallPhysics;
  readonly teleports: Vec3[] = [];

  constructor(hole: Hole, spawn: Vec3, velocity: Vec3 = { x: 0, y: 0, z: 0 }) {
    this.runtime = new HoleRuntime(this.physics, hole, this.builder);
    this.ball = new GolfBallPhysics(this.physics, spawn, BALL_OPTIONS);
    this.ball.body.setLinvel(velocity, true);
  }

  run(steps: number, stop?: () => boolean): void {
    for (let index = 0; index < steps; index += 1) {
      this.physics.step(STEP, (fixed) => {
        this.runtime.update(fixed);
        const effect = this.runtime.applyBallEffects(
          { position: this.ball.position, velocity: this.ball.velocity, radius: RADIUS },
          fixed,
          MASS,
        );
        if (effect.changed) {
          if (effect.position) {
            this.teleports.push({ ...effect.position });
            this.ball.body.setTranslation(effect.position, true);
          }
          this.ball.body.setLinvel(effect.velocity, true);
        }
        this.ball.update(fixed);
      });
      if (stop?.()) return;
    }
  }

  dispose(): void {
    this.runtime.dispose();
    this.builder.dispose();
    this.physics.dispose();
  }
}

